npc {
  map = "prontera", x = 160, y = 185, dir = 3, sprite = 116, name = "Arena Entrance",
  src = "817:other/arena.txt:28",
  on_click = function()
    local c
    mes "Want to go to the arena?"
    next()
    c = menu("Let's go!", "Nah..")
    if c == 1 then goto L_GOARENA elseif c == 2 then goto L_YAME end
    ::L_GOARENA::
    warp("prt_are_in", 31, 82)
    close()
    do return end
    ::L_YAME::
    close()
  end,
}

